{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Tetrabenazine, a close structural analogue sharing the methoxy-substituted benzo-fused tertiary amine core, had absolute oral bioavailability of 5.3% in a fasted patient, directly supporting F < 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Terameprocol, a lipophilic rigid plant-derived molecule with high assay transfer, showed absolute oral bioavailability of approximately 2% in patients, reinforcing that lipophilicity alone does not ensure F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "MK-458, a morphinan-like dopamine agonist with a phenol and tertiary amine, had absolute oral bioavailability of 4.1% (range 3.3-6.0%) in patients, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Cepharanthine, a bisbenzylisoquinoline alkaloid, had absolute oral bioavailability of 6-9% in humans, indicating extensive first-pass metabolism for this alkaloid class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All high-transfer experimental analogues exhibit absolute oral bioavailability well below 20% (tetrabenazine 0.1-8.5%, terameprocol ~2%, MK-458 ~4-5%, cepharanthine 6-9%). This consistent, direct evidence overrides the physicochemical prior and supports a low F prediction for the query.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule; reliance on analogues.",
    "The specific first-pass metabolism and transporter profile of the query are not directly characterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

